+
+// initGitCopy makes the copy a Git work tree of its own, never linked to the real repository:
+// a fresh repository with a throwaway identity, no remote and no hooks, whose HEAD is the
+// committed tree of root, fetched by path.
+func initGitCopy(s *sys.Session, root, clone string) error {
+	script := git.UnsetPrefix() + "git init -q && git config user.name 'Kogen Init' && git config user.email 'init@kogen.invalid' && " +
+		"git config commit.gpgsign false && git config core.hooksPath /dev/null && " +
+		"git fetch -q --no-tags " + initShellQuote(root) + " HEAD && git reset -q FETCH_HEAD"
+	res, err := s.Run(script, clone, sys.Options{KillGroupOnExit: true})
+	if err != nil {
+		return err
+	}
+	if res.Status != 0 {
+		return fmt.Errorf("making the init copy a Git work tree failed: %s", res.Output)
 	}
 	return nil
 }
